import pulp

# Define the problem
prob = pulp.LpProblem("Production_Planning", pulp.LpMinimize)

# Data
products = ['I', 'II', 'III']
quarters = [1, 2, 3, 4]

# Demand (contract orders)
demand = {
    'I': [1500, 1000, 2000, 1200],
    'II': [1500, 1500, 1200, 1500],
    'III': [1000, 2000, 1500, 2500]
}

# Production time per unit (hours)
prod_time = {'I': 2, 'II': 4, 'III': 3}

# Production capacity per quarter (hours)
capacity = 15000

# Late delivery penalty per unit per quarter
late_penalty = {'I': 20, 'II': 20, 'III': 10}

# Storage fee per unit per quarter
storage_cost = 5

# Required ending inventory at end of Q4
ending_inv = 150

# Decision variables
# x[p][q]: units of product p produced in quarter q
x = {}
for p in products:
    for q in quarters:
        if p == 'I' and q == 2:
            x[(p, q)] = pulp.LpVariable(f"x_{p}_{q}", lowBound=0, upBound=0)
        else:
            x[(p, q)] = pulp.LpVariable(f"x_{p}_{q}", lowBound=0)

# inv[p][q]: inventory of product p at end of quarter q
inv = {}
for p in products:
    for q in quarters:
        inv[(p, q)] = pulp.LpVariable(f"inv_{p}_{q}", lowBound=0)

# back[p][q]: backorder of product p at end of quarter q
back = {}
for p in products:
    for q in quarters:
        back[(p, q)] = pulp.LpVariable(f"back_{p}_{q}", lowBound=0)

# Objective function: minimize total cost (late delivery penalty + storage cost)
prob += (
    pulp.lpSum(
        late_penalty[p] * back[(p, q)] + storage_cost * inv[(p, q)]
        for p in products
        for q in quarters
    )
)

# Constraints

# 1. Flow balance for each product and quarter
# inv[p][q] - back[p][q] = inv[p][q-1] - back[p][q-1] + x[p][q] - demand[p][q]
# For q=1: inv[p][0] = 0, back[p][0] = 0
for p in products:
    for q in quarters:
        if q == 1:
            # inv[p][1] - back[p][1] = 0 - 0 + x[p][1] - demand[p][0] (demand index 0 for Q1)
            prob += (
                inv[(p, q)] - back[(p, q)] == x[(p, q)] - demand[p][q - 1]
            )
        else:
            # inv[p][q] - back[p][q] = inv[p][q-1] - back[p][q-1] + x[p][q] - demand[p][q]
            prob += (
                inv[(p, q)] - back[(p, q)] ==
                inv[(p, q - 1)] - back[(p, q - 1)] + x[(p, q)] - demand[p][q - 1]
            )

# 2. Production capacity constraint for each quarter
for q in quarters:
    prob += (
        pulp.lpSum(prod_time[p] * x[(p, q)] for p in products) <= capacity
    )

# 3. Product I cannot be produced in Q2 (already enforced by setting x['I'][2] to 0)

# 4. Ending inventory requirement at end of Q4
for p in products:
    prob += inv[(p, 4)] == ending_inv
    prob += back[(p, 4)] == 0

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Print results
print(f"Status: {pulp.LpStatus[prob.status]}")
print(f"Objective value (total cost): {pulp.value(prob.objective)}")
print()

print("Production quantities:")
for p in products:
    for q in quarters:
        print(f"  Product {p}, Quarter {q}: {x[(p, q)].value():.2f}")
print()

print("Inventory at end of each quarter:")
for p in products:
    for q in quarters:
        print(f"  Product {p}, Quarter {q}: {inv[(p, q)].value():.2f}")
print()

print("Backorders at end of each quarter:")
for p in products:
    for q in quarters:
        print(f"  Product {p}, Quarter {q}: {back[(p, q)].value():.2f}")
