inv = {}
for p in products:
    for t in quarters:
        inv[p][t] = pulp.LpVariable(f"inv_{p}_{t}", lowBound=0)

# back[p][t]: backlogged units of product p at end of quarter t
back = {}
for p in products:
    for t in quarters:
        back[p][t] = pulp.LpVariable(f"back_{p}_{t}", lowBound=0)

